package main

import (
	"database/sql"
	"encoding/json"
	"net/http"
	"os"

	_ "github.com/mattn/go-sqlite3"
)

func main() {
	port := os.Getenv("PORT")
	if port == "" {
		port = "3000"
	}

	db, _ := sql.Open("sqlite3", ":memory:")
	db.SetMaxOpenConns(5)
	db.SetMaxIdleConns(2)
	db.Exec("CREATE TABLE IF NOT EXISTS items (id INTEGER PRIMARY KEY, name TEXT)")
	for i := 1; i <= 5; i++ {
		name := "item-" + strconv.Itoa(i)
		db.Exec("INSERT INTO items (name) VALUES (?)", name)
	}

	http.HandleFunc("/items", func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Content-Type", "application/json")
		rows, _ := db.Query("SELECT id, name FROM items ORDER BY id")
		var items []map[string]interface{}
		for rows.Next() {
			var id int
			var name string
			rows.Scan(&id, &name)
			items = append(items, map[string]interface{}{"id": id, "name": name})
		}
		json.NewEncoder(w).Encode(items)
	})

	http.HandleFunc("/health", func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Content-Type", "application/json")
		stats := db.Stats()
		json.NewEncoder(w).Encode(map[string]interface{}{
			"status": "ok",
			"pool":   map[string]interface{}{"total": 5, "active": stats.InUse, "idle": stats.Idle, "waiting": stats.WaitCount},
		})
	})

	http.ListenAndServe(":"+port, nil)
}

